"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { PageCTA, PageHeader, PageShell } from "~/components/PageLayout/PageLayout";
import { EMAIL } from "~/utils/message";
import "./ProductsPage.css";
import PRODUCTS, { CATEGORIES } from "./product";
import { ProductCategory } from "./product.types";

const ALL = "All" as const;
type FilterValue = ProductCategory | typeof ALL;

const emailSubject = "Product Suggestion";

const emailBody = `Hi Pinktra team,

I came across Pinktra's products page and wanted to get in touch.

Message:
-

Best regards,
`;

export default function ProductsPage() {
  const [activeFilter, setActiveFilter] = useState<FilterValue>(ALL);

  const filteredProducts = useMemo(() => {
    if (activeFilter === ALL) return PRODUCTS;
    return PRODUCTS.filter((product) => product.category === activeFilter);
  }, [activeFilter]);

  return (
    <PageShell className="products-page">
      <div className="app-container page-container">
        <PageHeader
          badge="Pinktra Products"
          title="Tools Built for Real Life"
          description={
            <>
              A growing collection of AI tools, developer tools, productivity apps, and finance
              tools — built by Pinktra to help you apply what you learn. Tap any card to visit the
              product.
            </>
          }
        />

        <ul className="pp-filters" aria-label="Filter products by category">
          <li>
            <button
              type="button"
              className={`pp-filter-btn${activeFilter === ALL ? " pp-filter-active" : ""}`}
              aria-pressed={activeFilter === ALL}
              onClick={() => setActiveFilter(ALL)}
            >
              All
            </button>
          </li>
          {CATEGORIES.map((category) => (
            <li key={category}>
              <button
                type="button"
                className={`pp-filter-btn${activeFilter === category ? " pp-filter-active" : ""}`}
                aria-pressed={activeFilter === category}
                onClick={() => setActiveFilter(category)}
              >
                {category}
              </button>
            </li>
          ))}
        </ul>

        {filteredProducts.length === 0 ? (
          <p className="pp-empty">No products in this category yet. Check back soon.</p>
        ) : (
          <ul className="page-grid pp-grid" aria-label="Products and tools">
            {filteredProducts.map((product) => {
              const hostname = new URL(product.url).hostname.replace(/^www\./, "");

              return (
                <li key={product.slug} className="page-grid-item">
                  <a
                    href={product.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="page-card glass-panel pp-card"
                    aria-label={`Visit ${product.title} (opens in a new tab)`}
                  >
                    <div className="pp-card-top">
                      <span className="pp-card-icon glass-panel">
                        <img
                          src={`${product.url}/android-chrome-512x512.png`}
                          alt={product.title}
                          aria-hidden="true"
                          loading="lazy"
                        />
                      </span>
                      <div className="pp-card-heading">
                        <span className="pp-card-category">{product.category}</span>
                        <h2 className="pp-card-title">{product.title}</h2>
                      </div>
                    </div>

                    <p className="pp-card-desc">{product.description}</p>

                    <ul className="pp-card-tags" aria-label={`Tags for ${product.title}`}>
                      {product.tags.map((tag) => (
                        <li key={tag} className="pp-tag">
                          {tag}
                        </li>
                      ))}
                    </ul>

                    <div className="pp-card-footer">
                      <span className="pp-card-host">{hostname}</span>
                      <span className="pp-card-cta">
                        Visit <span aria-hidden="true">↗</span>
                      </span>
                    </div>
                  </a>
                </li>
              );
            })}
          </ul>
        )}

        <PageCTA
          className="pp-cta"
          title="Have an idea for a product?"
          description={
            <>
              If there&apos;s a tool or product you&apos;d like to see Pinktra build next, we&apos;d
              love to hear about it.
            </>
          }
        >
          <Link href="/contact" className="page-button page-button-primary">
            Contact Us
          </Link>

          <a
            href={`mailto:${EMAIL}?subject=${encodeURIComponent(emailSubject)}&body=${encodeURIComponent(emailBody)}`}
            className="page-button page-button-secondary"
          >
            Email Us
          </a>
        </PageCTA>
      </div>
    </PageShell>
  );
}
